<?php require_once __DIR__ . '/../includes/bootstrap.php';require_login('admin');$p=database();$queries=['Users'=>'SELECT COUNT(*) FROM users','Job seekers'=>"SELECT COUNT(*) FROM users WHERE role='seeker'",'Employers'=>"SELECT COUNT(*) FROM users WHERE role='employer'",'Jobs'=>'SELECT COUNT(*) FROM jobs','Applications'=>'SELECT COUNT(*) FROM applications','Courses'=>'SELECT COUNT(*) FROM courses','Quiz attempts'=>'SELECT COUNT(*) FROM quiz_attempts'];page_header('Admin dashboard');?><h1>Platform dashboard</h1><section class="stats"><?php foreach($queries as $label=>$sql):?><div class="stat"><strong><?=e($p->query($sql)->fetchColumn())?></strong><?=e($label)?></div><?php endforeach;?></section><?php $rate=$p->query('SELECT COALESCE(ROUND(AVG(passed)*100,1),0) FROM quiz_attempts')->fetchColumn();?><p class="notice">Quiz pass rate: <?=e($rate)?>%</p><p><a class="button" href="users.php">Users</a> <a class="button secondary" href="jobs.php">Jobs</a> <a class="button secondary" href="categories.php">Categories</a> <a class="button secondary" href="courses.php">Courses</a> <a class="button secondary" href="applications.php">Applications</a> <a class="button secondary" href="quiz-statistics.php">Quiz statistics</a></p><?php page_footer(); ?>